pub mod migrations;

use std::fs;

use rusqlite::Connection;
use tauri::{AppHandle, Manager};

pub fn open_database(app: &AppHandle) -> Result<Connection, String> {
    let app_data_dir = app
        .path()
        .app_data_dir()
        .map_err(|error| format!("Failed to resolve app data directory: {error}"))?;

    fs::create_dir_all(&app_data_dir)
        .map_err(|error| format!("Failed to create app data directory: {error}"))?;

    let database_path = app_data_dir.join("mission-control.db");

    let connection = Connection::open(&database_path)
        .map_err(|error| format!("Failed to open Mission Control database: {error}"))?;

    connection
        .execute_batch(
            "
            PRAGMA foreign_keys = ON;
            PRAGMA journal_mode = WAL;
            ",
        )
        .map_err(|error| format!("Failed to configure Mission Control database: {error}"))?;

    migrations::run(&connection)
        .map_err(|error| format!("Failed to run Mission Control migrations: {error}"))?;

    Ok(connection)
}

use rusqlite::Connection;

const MIGRATION_001: &str =
    include_str!("../../migrations/001_initial.sql");

pub fn run(connection: &Connection) -> rusqlite::Result<()> {
    let version: i64 =
        connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;

    if version < 1 {
        connection.execute_batch("BEGIN IMMEDIATE;")?;

        if let Err(error) = connection.execute_batch(MIGRATION_001) {
            let _ = connection.execute_batch("ROLLBACK;");
            return Err(error);
        }

        if let Err(error) = connection.pragma_update(None, "user_version", 1) {
            let _ = connection.execute_batch("ROLLBACK;");
            return Err(error);
        }

        connection.execute_batch("COMMIT;")?;
    }

    Ok(())
}

use rusqlite::{params, Connection, OptionalExtension};
