    project_id: String,
    state: State<'_, AppState>,
) -> Result<Project, String> {
    let connection = state
        .database
        .lock()
        .map_err(|_| "Mission Control database lock was poisoned.".to_string())?;

    project_service::get_project(&connection, &project_id)?
        .ok_or_else(|| "Project not found.".into())
}

