class LocalProjectBackend implements ProjectBackend {
  list(): Promise<Project[]> {
    return invoke<Project[]>("project_list");
  }

  get(projectId: string): Promise<Project> {
    return invoke<Project>("project_get", {
      projectId
    });
  }

  create(
    input: CreateProjectInput
  ): Promise<Project> {
    return invoke<Project>("project_create", {
      input
    });
  }

  update(
    projectId: string,
    input: UpdateProjectInput
  ): Promise<Project> {
    return invoke<Project>("project_update", {
      projectId,
      input
    });
  }

  archive(projectId: string): Promise<void> {
    return invoke<void>("project_archive", {
      projectId
    });
  }
}

export class LocalBackend implements MissionControlBackend {
  readonly projects: ProjectBackend =
    new LocalProjectBackend();

  capabilities(): Promise<BackendCapabilities> {
    return invoke<BackendCapabilities>(
      "backend_capabilities"
    );
  }
}

import type { MissionControlBackend } from "../../../backend/types";

import type {
  CreateProjectInput,
  UpdateProjectInput
} from "../types/project";

export function createProjectsApi(
  backend: MissionControlBackend
) {
  return {
    list: () => backend.projects.list(),

    get: (projectId: string) =>
      backend.projects.get(projectId),

    create: (input: CreateProjectInput) =>
      backend.projects.create(input),

    update: (
      projectId: string,
      input: UpdateProjectInput
    ) =>
      backend.projects.update(
        projectId,
        input
      ),

    archive: (projectId: string) =>
      backend.projects.archive(projectId)
  };
}

import { useQuery } from "@tanstack/react-query";

import { useBackend } from "../../../backend/BackendProvider";
import { createProjectsApi } from "../api/projectsApi";

export const projectQueryKeys = {
  all: ["projects"] as const,

  detail: (projectId: string) =>
    ["projects", projectId] as const
};

export function useProjects() {
  const backend = useBackend();
  const api = createProjectsApi(backend);

  return useQuery({
    queryKey: projectQueryKeys.all,
    queryFn: () => api.list()
  });
}
